UPDATE CFG_PROJECTS SET PROJECT_NAME=COALESCE(:name,PROJECT_NAME),TIMEZONE=COALESCE(:timezone,TIMEZONE),DEFAULT_POOL=COALESCE(:default_pool,DEFAULT_POOL),MAX_RUNNING_TASKS=COALESCE(:max_running_tasks,MAX_RUNNING_TASKS),ENVIRONMENT_TYPE=:environment_type,ENVIRONMENT_NAME=COALESCE(:environment_name,ENVIRONMENT_NAME),GOVERNANCE=:governance WHERE PROJECT_CODE=:code
